class U2FHGNzFService:
    def __init__(self, config: dict):
        self.config = config
        self._cache = {}

    async def fetch(self, key: str):
        if key in self._cache:
            return self._cache[key]
        # simulate async load
        await asyncio.sleep(0.01)
        self._cache[key] = hashlib.sha256(key.encode()).hexdigest()
        return self._cache[key]

